window.__ModuleLoader__.load({
	id: "dsh-plugin-avatar",
	factory: (require) => {
		var module = { exports: {} };
		var exports = module.exports;
		Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });

		const DEFAULT_SRC = "data:image/png;base64,";
		const RESP = '[data-chat-group-part="response"]';
		const USER = '[data-slot*="user.text"],[data-slot*="user.images"]';
		const KEY = "dshAvatar.v1";

		function load() {
			try {
				const raw = localStorage.getItem(KEY);
				if (!raw) return { size: 36, src: DEFAULT_SRC };
				const o = JSON.parse(raw);
				return {
					size: typeof o.size === "number" && o.size >= 16 && o.size <= 96 ? o.size : 36,
					src: typeof o.src === "string" && o.src ? o.src : DEFAULT_SRC
				};
			} catch (e) {
				return { size: 36, src: DEFAULT_SRC };
			}
		}

		function save(s) {
			try {
				localStorage.setItem(KEY, JSON.stringify({ size: s.size, src: s.src === DEFAULT_SRC ? "" : s.src }));
			} catch (e) {}
		}

		let state = load();

		function makeImg(src, side, isMine) {
			const img = document.createElement("img");
			img.src = src;
			img.setAttribute("alt", "");
			img.style.cssText =
				"position:absolute;top:0;width:" + state.size + "px;height:" + state.size + "px;" +
				"border-radius:50%;display:block;user-select:none;" +
				"box-shadow:0 1px 3px rgba(0,0,0,.12);" +
				(side === "left" ? "left:" + (-state.size - 22) + "px;" : "right:" + (-state.size - 22) + "px;") +
				(isMine ? "cursor:pointer;pointer-events:auto;" : "pointer-events:none;");
			return img;
		}

		function userAvatarSrc() {
			const el = document.querySelector("[data-avatar-status] img");
			return el && el.src ? el.src : null;
		}

		function applySizes() {
			document.querySelectorAll("img[data-dsh-avatar]").forEach((img) => {
				const side = img.getAttribute("data-dsh-avatar") === "me" ? "left" : "right";
				img.style.width = state.size + "px";
				img.style.height = state.size + "px";
				img.style[side] = -(state.size + 22) + "px";
				if (img.getAttribute("data-dsh-avatar") === "me") img.src = state.src;
			});
		}

		function decorateAssistant(el) {
			if (!el || el.querySelector("img[data-dsh-avatar=me]")) return;
			const cs = getComputedStyle(el);
			if (cs.position === "static") el.style.position = "relative";
			const img = makeImg(state.src, "left", true);
			img.setAttribute("data-dsh-avatar", "me");
			img.title = "双击设置头像";
			img.addEventListener("dblclick", (ev) => {
				ev.preventDefault();
				ev.stopPropagation();
				openSettings();
			});
			el.appendChild(img);
		}

		function decorateUser(el) {
			let host = el;
			for (let i = 0; i < 6 && host; i++) {
				if (host.offsetWidth > 300) break;
				host = host.parentElement;
			}
			if (!host) return;
			if (host.querySelector("img[data-dsh-avatar=user]")) return;
			const src = userAvatarSrc();
			if (!src) return;
			const cs = getComputedStyle(host);
			if (cs.position === "static") host.style.position = "relative";
			const img = makeImg(src, "right", false);
			img.setAttribute("data-dsh-avatar", "user");
			host.appendChild(img);
		}

		function scan() {
			document.querySelectorAll(RESP).forEach(decorateAssistant);
			document.querySelectorAll(USER).forEach(decorateUser);
		}

		let scheduled = false;
		function schedule() {
			if (scheduled) return;
			scheduled = true;
			requestAnimationFrame(() => {
				scheduled = false;
				scan();
			});
		}

		function openSettings() {
			if (document.getElementById("dsh-avatar-dlg")) return;

			const wrap = document.createElement("div");
			wrap.id = "dsh-avatar-dlg";
			wrap.style.cssText =
				"position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:99999;" +
				"display:flex;align-items:center;justify-content:center;";

			const box = document.createElement("div");
			box.style.cssText =
				"background:#fff;color:#1f2328;border-radius:14px;padding:20px 22px;width:330px;" +
				"box-shadow:0 12px 40px rgba(0,0,0,.25);font:14px/1.6 system-ui,-apple-system,Segoe UI,sans-serif;";
			box.innerHTML =
				'<div style="font-weight:600;font-size:15px;margin-bottom:14px">头像设置</div>' +
				'<div style="display:flex;align-items:center;gap:14px;margin-bottom:16px">' +
				'  <img id="dsh-av-preview" style="width:56px;height:56px;border-radius:50%;object-fit:cover;box-shadow:0 1px 4px rgba(0,0,0,.18)">' +
				'  <label style="flex:1;font-size:12px;color:#57606a;cursor:pointer">' +
				'    <span style="display:inline-block;padding:6px 10px;border:1px solid #d0d7de;border-radius:8px;background:#f6f8fa;color:#1f2328">选择图片</span>' +
				'    <input id="dsh-av-file" type="file" accept="image/*" style="display:none">' +
				'  </label>' +
				'</div>' +
				'<div style="margin-bottom:18px">' +
				'  <div style="display:flex;justify-content:space-between;font-size:12px;color:#57606a;margin-bottom:6px">' +
				'    <span>大小</span><span id="dsh-av-size-label"></span>' +
				'  </div>' +
				'  <input id="dsh-av-size" type="range" min="16" max="96" step="2" style="width:100%">' +
				'</div>' +
				'<div style="display:flex;justify-content:space-between;align-items:center">' +
				'  <button id="dsh-av-reset" style="border:none;background:transparent;color:#0969da;padding:6px 2px;cursor:pointer;font:inherit">恢复默认</button>' +
				'  <button id="dsh-av-close" style="border:none;background:#1f2328;color:#fff;border-radius:8px;padding:7px 18px;cursor:pointer;font:inherit">完成</button>' +
				'</div>';

			wrap.appendChild(box);
			document.body.appendChild(wrap);

			const preview = box.querySelector("#dsh-av-preview");
			const file = box.querySelector("#dsh-av-file");
			const size = box.querySelector("#dsh-av-size");
			const label = box.querySelector("#dsh-av-size-label");

			preview.src = state.src;
			size.value = String(state.size);
			label.textContent = state.size + " px";

			file.addEventListener("change", () => {
				const f = file.files && file.files[0];
				if (!f) return;
				const reader = new FileReader();
				reader.onload = () => {
					state.src = String(reader.result);
					preview.src = state.src;
					save(state);
					applySizes();
				};
				reader.readAsDataURL(f);
			});

			size.addEventListener("input", () => {
				state.size = parseInt(size.value, 10) || 36;
				label.textContent = state.size + " px";
				save(state);
				applySizes();
			});

			box.querySelector("#dsh-av-reset").addEventListener("click", () => {
				state = { size: 36, src: DEFAULT_SRC };
				preview.src = DEFAULT_SRC;
				size.value = "36";
				label.textContent = "36 px";
				save(state);
				applySizes();
			});

			const close = () => wrap.remove();
			box.querySelector("#dsh-av-close").addEventListener("click", close);
			wrap.addEventListener("click", (ev) => {
				if (ev.target === wrap) close();
			});
		}

		const inject = [];

		function apply() {
			scan();
			const mo = new MutationObserver(schedule);
			mo.observe(document.body, { childList: true, subtree: true });
		}

		exports.apply = apply;
		exports.inject = inject;
		return module.exports;
	}
});
